#!/usr/bin/env node
// U1 黑盒验证：GET /entries 无参数全量 + 合法 month=YYYY-MM 过滤。
// 计划场景：1) 无参数全量；2) 合法月份过滤（含不匹配月份的空结果探针）。
// 用法：node verify-month-filter.cjs <repo-root>
const { spawn } = require('child_process');
const http = require('http');
const path = require('path');

const REPO = path.resolve(process.argv[2] || process.cwd());
const PORT = 3000;
const results = [];
let failures = 0;

function check(name, ok, detail) {
  results.push({ name, ok, detail });
  if (!ok) failures += 1;
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${detail ? ' :: ' + detail : ''}`);
}

function req(method, urlPath, body) {
  return new Promise((resolve, reject) => {
    const r = http.request(
      { host: '127.0.0.1', port: PORT, path: urlPath, method,
        headers: body ? { 'content-type': 'application/json' } : {} },
      (res) => {
        let data = '';
        res.on('data', (c) => { data += c; });
        res.on('end', () => resolve({ status: res.statusCode, body: data }));
      });
    r.on('error', reject);
    if (body) r.write(JSON.stringify(body));
    r.end();
  });
}

const monthOf = (ts) => new Date(ts).toISOString().slice(0, 7);

async function waitForServer(child) {
  const deadline = Date.now() + 8000;
  for (;;) {
    if (child.exitCode !== null) throw new Error(`server exited early with code ${child.exitCode}`);
    if (Date.now() > deadline) throw new Error('timeout waiting for server listen');
    try { await req('GET', '/entries'); return; } catch (_) { /* retry */ }
    await new Promise((r) => setTimeout(r, 150));
  }
}

(async () => {
  const child = spawn(process.execPath, [path.join(REPO, 'src', 'server.js')], { cwd: REPO, stdio: 'ignore' });
  try {
    await waitForServer(child);

    // 准备数据：3 条带唯一 note 的记录
    const notes = ['mfu-alpha', 'mfu-beta', 'mfu-gamma'];
    for (let i = 0; i < notes.length; i += 1) {
      const r = await req('POST', '/entries', { amount: (i + 1) * 10, note: notes[i] });
      check(`post-entry-${i + 1}`, r.status === 200, `status=${r.status} body=${r.body}`);
    }

    // 场景 1：无参数全量
    const all = JSON.parse((await req('GET', '/entries')).body);
    const allNotes = all.map((e) => e.note).sort();
    check('no-param-returns-all', Array.isArray(all) && allNotes.join(',') === notes.slice().sort().join(','),
      `count=${all.length} notes=${allNotes.join('|')}`);

    // 场景 2：合法月份过滤（期望月份从真实 ts 派生，与服务端同一 UTC 语义）
    const months = [...new Set(all.map((e) => monthOf(e.ts)))];
    for (const m of months) {
      const matched = JSON.parse((await req('GET', `/entries?month=${m}`)).body);
      const expected = all.filter((e) => monthOf(e.ts) === m).map((e) => e.note).sort();
      check(`month-${m}-filter`, Array.isArray(matched) &&
        matched.map((e) => e.note).sort().join(',') === expected.join(','),
        `matched=${matched.length} expected=${expected.length}`);
    }
    // 不匹配月份（回拨 32 天必然跨月）应返回空集
    const otherMonth = monthOf(Date.now() - 32 * 86400000);
    const other = JSON.parse((await req('GET', `/entries?month=${otherMonth}`)).body);
    check(`month-${otherMonth}-no-match-empty`, Array.isArray(other) && other.length === 0,
      `count=${other.length}`);
  } catch (e) {
    failures += 1;
    console.log(`FAIL harness-error :: ${e && e.message}`);
  } finally {
    child.kill('SIGTERM');
  }
  console.log(`SUMMARY total=${results.length + (failures && !results.length ? 1 : 0)} failures=${failures}`);
  process.exit(failures === 0 ? 0 : 1);
})();

